import{_ as r,o as a,c as o,a2 as e}from"./chunks/framework.CYjxsSA2.js";const b=JSON.parse('{"title":"军团智能体","description":"","frontmatter":{},"headers":[],"relativePath":"guide/army.md","filePath":"guide/army.md"}'),d={name:"guide/army.md"};function n(l,t,s,i,h,g){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="军团智能体" tabindex="-1">军团智能体 <a class="header-anchor" href="#军团智能体" aria-label="Permalink to &quot;军团智能体&quot;">​</a></h1><p>军团是 VAELOR 的核心工作区 —— 用一句话下达任务，它对目标发起多轮自动化作业，直到任务完成。</p><h2 id="工作区布局" tabindex="-1">工作区布局 <a class="header-anchor" href="#工作区布局" aria-label="Permalink to &quot;工作区布局&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>内容</th></tr></thead><tbody><tr><td><strong>左侧会话栏</strong></td><td>会话列表：搜索、分组排序、置顶与归档、卡片 / 列表两种视图</td></tr><tr><td><strong>会话头</strong></td><td>当前会话名、运行状态、视图切换</td></tr><tr><td><strong>主对话区</strong></td><td>任务描述、工具卡、证据与结论，实时流式输出</td></tr><tr><td><strong>右侧停靠面板</strong></td><td>并行任务、浏览器画面与请求响应、工具调用汇总、军团编辑过的文件</td></tr></tbody></table><p>右侧面板宽度可拖动、可收起，用来在看结论的同时瞄一眼现场。</p><h2 id="开场-选一个角色-说一句话" tabindex="-1">开场：选一个角色，说一句话 <a class="header-anchor" href="#开场-选一个角色-说一句话" aria-label="Permalink to &quot;开场：选一个角色，说一句话&quot;">​</a></h2><p>新建会话时选一个角色：</p><table tabindex="0"><thead><tr><th>角色</th><th>定位</th></tr></thead><tbody><tr><td><strong>默认角色</strong></td><td>纯对话助手，参数调优与日常问答，不调用工具</td></tr><tr><td><strong>红队角色</strong></td><td>打点闭环：全工具链、GetShell / RCE、内网路径评估</td></tr><tr><td><strong>渗透角色</strong></td><td>SRC / 日常 Web 渗透：挖洞、浏览器取证、HTTP 报告</td></tr><tr><td><strong>CTF 角色</strong></td><td>解题导向，目标明确地深挖单题</td></tr><tr><td><strong>侦察角色</strong></td><td>资产侦察：指纹、框架、组件与攻击面整理，不挖洞</td></tr></tbody></table><p>角色可配置系统提示词、可用工具开关与 Skills 挂载，也可以自建角色。</p><p>然后直接写任务，例如：</p><blockquote><p>对 <a href="http://10.1.5.1:1180/" target="_blank" rel="noreferrer">http://10.1.5.1:1180/</a> 进行授权渗透测试，全面发现并验证漏洞，输出报告。</p></blockquote><h2 id="计划模式-先看计划-再放行动手" tabindex="-1">计划模式：先看计划，再放行动手 <a class="header-anchor" href="#计划模式-先看计划-再放行动手" aria-label="Permalink to &quot;计划模式：先看计划，再放行动手&quot;">​</a></h2><p>点输入框工具栏的<strong>计划</strong>按钮，本轮军团只做被动侦察与信息收集，产出一份计划卡：测什么、怎么测、预期确认什么、风险与前置条件。</p><p>确认无误后点**「批准并执行」**，下一轮即按计划开工。计划模式下主动扫描、爆破、写文件、派发子任务等动作会被拒绝。</p><h2 id="权限模式-三档管控" tabindex="-1">权限模式：三档管控 <a class="header-anchor" href="#权限模式-三档管控" aria-label="Permalink to &quot;权限模式：三档管控&quot;">​</a></h2><p>点输入框工具栏的<strong>权限</strong>按钮切换。这是<strong>执行前的强制拦截</strong>，被拦的操作不会真正执行。</p><table tabindex="0"><thead><tr><th>档位</th><th>能做什么</th></tr></thead><tbody><tr><td><strong>只读</strong></td><td>仅侦察与读取；命令执行与写操作一律禁止</td></tr><tr><td><strong>工作区写入</strong></td><td>可写入工作区产物、执行 PoC 级命令；破坏性 / 横向移动 / 远程执行仍被拦</td></tr><tr><td><strong>完全访问</strong></td><td>不做限制</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">完全访问不会被记住</p><p>重新打开程序后会回落为「工作区写入」，界面顶部显示提示，点**「恢复完全访问」**并二次确认即可改回。</p></div><h2 id="高危操作人工确认" tabindex="-1">高危操作人工确认 <a class="header-anchor" href="#高危操作人工确认" aria-label="Permalink to &quot;高危操作人工确认&quot;">​</a></h2><p>即便在完全访问档，以下动作执行前也会弹确认卡：</p><table tabindex="0"><thead><tr><th>风险类型</th><th>举例</th></tr></thead><tbody><tr><td><strong>破坏性</strong></td><td>删除系统目录、格式化、关机重启</td></tr><tr><td><strong>植入 / 反弹</strong></td><td>反弹 Shell、下载并执行植入体</td></tr><tr><td><strong>横向移动</strong></td><td>SSH 远程执行、<code>impacket</code> / <code>psexec</code> / <code>wmiexec</code> 系列</td></tr><tr><td><strong>远程执行</strong></td><td>批量远程扫描与动作</td></tr></tbody></table><p>确认卡可勾选「批准并在本会话内自动批准」；超时未响应视为拒绝，动作留痕可查。普通 PoC 命令不会打扰。</p><h2 id="执行隔离" tabindex="-1">执行隔离 <a class="header-anchor" href="#执行隔离" aria-label="Permalink to &quot;执行隔离&quot;">​</a></h2><p>军团的命令可在<strong>本机</strong>或<strong>隔离环境</strong>（Kali Docker 容器 / WSL）中执行，档位在<strong>系统配置 → 智能体 → 执行环境</strong>中设定：</p><table tabindex="0"><thead><tr><th>档位</th><th>行为</th></tr></thead><tbody><tr><td><strong>不隔离</strong></td><td>命令在本机执行</td></tr><tr><td><strong>优先隔离</strong>（默认）</td><td>有可用容器 / WSL 就进隔离环境，否则本机执行</td></tr><tr><td><strong>必须隔离</strong></td><td>没有可用隔离环境即<strong>拒绝执行</strong>，不会回落本机</td></tr></tbody></table><p>每条命令的结果都标注它<strong>在哪跑的</strong>（隔离执行 / 本机执行）。工具箱的安装见 <a href="/vaelor/advanced/docker.html">Kali 工具箱</a>。</p><h2 id="模型配置" tabindex="-1">模型配置 <a class="header-anchor" href="#模型配置" aria-label="Permalink to &quot;模型配置&quot;">​</a></h2><p><strong>系统配置 → 大模型配置</strong>：</p><ul><li><strong>开箱即用预设</strong> —— DeepSeek、GLM 智谱、通义千问，填 API Key 即用</li><li><strong>Anthropic Claude</strong> —— 原生接口格式</li><li><strong>自定义</strong> —— 任意 OpenAI 兼容端点（中转、私有化部署均可）</li></ul><p>多个 Provider 可并存，随时启用 / 禁用、切换默认模型；每个 Provider 可维护模型列表并做连通性验证。每轮对话的 Token 消耗按会话与项目汇总。</p><h2 id="会话与记忆" tabindex="-1">会话与记忆 <a class="header-anchor" href="#会话与记忆" aria-label="Permalink to &quot;会话与记忆&quot;">​</a></h2><ul><li>同一会话内上下文跨轮次保留，长对话会自动压缩，不必手工开新会话</li><li>会话可置顶、归档到文件夹，每个会话可单独设定模型参数</li><li>工具执行异常时会自动拉起恢复通道，已完成的调用不重复执行</li></ul><h2 id="发现与报告" tabindex="-1">发现与报告 <a class="header-anchor" href="#发现与报告" aria-label="Permalink to &quot;发现与报告&quot;">​</a></h2><ul><li>验证过的发现写入项目<strong>漏洞账本</strong>，在<a href="/vaelor/guide/vulnreports.html">漏洞管理</a>按严重度分诊汇总</li><li>侦察报告按资产归集，可导出 Markdown / PDF</li><li>交付前会做一次自检，拦截「有结论、无证据」的条目</li></ul><h2 id="消息通知" tabindex="-1">消息通知 <a class="header-anchor" href="#消息通知" aria-label="Permalink to &quot;消息通知&quot;">​</a></h2><p>配置飞书 / 企业微信 Webhook 后，高危漏洞确认等关键事件会自动推送，可按严重等级设置阈值。详见<a href="/vaelor/advanced/notify.html">消息通知</a>。</p><h2 id="扩展" tabindex="-1">扩展 <a class="header-anchor" href="#扩展" aria-label="Permalink to &quot;扩展&quot;">​</a></h2><ul><li><strong>Skills</strong> —— 技能文件按需挂载到角色</li><li><strong>MCP</strong> —— 接入外部工具服务器，扩展军团能力边界</li><li><strong>钩子（Hooks）</strong> —— 挂接外部程序观察军团动作，或在工具执行前放行 / 拒绝</li></ul><h2 id="相关配置" tabindex="-1">相关配置 <a class="header-anchor" href="#相关配置" aria-label="Permalink to &quot;相关配置&quot;">​</a></h2><ul><li><strong>默认参数</strong> —— 系统配置 → 智能体 → 全局行为：默认模型、上下文窗口、最大输出、重试与超时</li><li><strong>执行环境</strong> —— 隔离档位与工具箱</li><li><strong>代理</strong> —— 军团探测的出口与 WAF 封禁后的切换，见<a href="/vaelor/advanced/proxy.html">代理与网络出口</a></li></ul>',40)])])}const p=r(d,[["render",n]]);export{b as __pageData,p as default};
